mapper.insert:
/* 알림 발송 이력 등록 */
INSERT INTO NOTI_SNDNG_LOG
     ( MBR_SN
     , SCHDL_SN
     , NOTI_TYPE_CD
     , NOTI_CHNL_CD
     , SNDNG_RSLT_CD
     , BFHD_NOTI_CD
     , RTRY_NMTM
     , SCHDL_YMD
     , SNDNG_DT
     , REG_DT
     , MDFCN_DT
     , RGTR_ID
     , MDFR_ID )
VALUES
     ( #{mbrSn}
     , #{schdlSn}
     , #{notiTypeCd}
     , #{notiChnlCd}
     , #{sndngRsltCd}
     , #{bfhdNotiCd}
     , #{rtryNmtm}
     , #{schdlYmd}
     , NOW()
     , NOW()
     , NOW()
     , #{rgtrId}
     , #{mdfrId} )

mapper.update:
/* 알림 발송 결과 수정 */
UPDATE NOTI_SNDNG_LOG
   SET SNDNG_RSLT_CD = #{sndngRsltCd}
     , RTRY_NMTM = #{rtryNmtm}
     , FAIL_RSN = #{failRsn}
     , SNDNG_DT = NOW()
     , MDFR_ID = #{actorId}
     , MDFCN_DT = NOW()
 WHERE NOTI_SNDNG_LOG_SN = #{notiSndngLogSn}

mapper.select:
/* 관리자 알림 발송 이력 목록 조회 : 탈퇴 회원 행도 포함 */ SELECT L.NOTI_SNDNG_LOG_SN , L.MBR_SN , M.MBR_NCNM , L.NOTI_TYPE_CD , L.NOTI_CHNL_CD , L.SNDNG_RSLT_CD , L.RTRY_NMTM , L.FAIL_RSN , L.SNDNG_DT FROM NOTI_SNDNG_LOG L LEFT JOIN MBR M ON M.MBR_SN = L.MBR_SN
AND L.SNDNG_DT >= #{bgngYmd}
AND L.SNDNG_DT < DATE_ADD(#{endYmd}, INTERVAL 1 DAY)
AND L.NOTI_CHNL_CD = #{notiChnlCd}
AND L.NOTI_TYPE_CD = #{notiTypeCd}
AND L.SNDNG_RSLT_CD = #{sndngRsltCd}
ORDER BY L.SNDNG_DT DESC , L.NOTI_SNDNG_LOG_SN DESC
